{
  "solution": "def max_removable_boxes(r, c, heights):\n    # Compute the three views\n    front_view = [max(row) for row in heights]\n    top_view = [max(col) for col in zip(*heights)]\n    left_view = [max(heights[i][j] for i in range(r)) for j in range(c)]\n\n    # Total boxes in the original grid\n    total_boxes = sum(sum(row) for row in heights)\n\n    # Compute the minimal boxes needed to preserve the three views\n    minimal_boxes = 0\n    for i in range(r):\n        for j in range(c):\n            minimal_boxes += max(front_view[i], top_view[j], left_view[j])\n\n    # The maximum number of boxes that can be removed\n    return total_boxes - minimal_boxes\n\n\nif __name__ == \"__main__\":\n    import sys\n    data = sys.stdin.read().strip().split()\n    if not data:\n        sys.exit(0)\n    it = iter(data)\n    r = int(next(it))\n    c = int(next(it))\n    heights = [[int(next(it)) for _ in range(c)] for _ in range(r)]\n    result = max_removable_boxes(r, c, heights)\n    print(result)\n"
}
